<?php use VO\Support\Template; ob_start(); ?><h1>Pago de <?= Template::e($payment['order_number']) ?></h1><section class="card"><p><strong>Estado:</strong> <?= Template::e($payment['state']) ?> · <strong>Método:</strong> <?= Template::e($payment['method']) ?> · <strong>Sucursal:</strong> <?= Template::e($payment['branch_name']) ?></p><p><strong>Total:</strong> $ <?= number_format((int)$payment['amount_cents']/100,2,',','.') ?></p><?php if($payment['proof_path']):?><p><a href="/admin/pagos/<?= (int)$payment['id'] ?>/comprobante">Ver comprobante</a></p><?php endif;?></section><?php if($payment['method']==='transfer'&&$payment['state']==='pending_verification'):?><section class="card"><form method="post" action="/admin/pagos/<?= (int)$payment['id'] ?>/verificar"><input type="hidden" name="csrf" value="<?= Template::e($csrf) ?>"><button class="btn">Verificar transferencia</button></form><form method="post" action="/admin/pagos/<?= (int)$payment['id'] ?>/rechazar"><input type="hidden" name="csrf" value="<?= Template::e($csrf) ?>"><label>Motivo <input name="reason" maxlength="191"></label><button class="btn secondary">Rechazar transferencia</button></form></section><?php endif;?><?php $content=ob_get_clean();$title='Pago '.$payment['order_number'];require __DIR__.'/layout.php';?>
